const tabId = 583778164;
const pageDetails = await browserjs(tabId, () => {
  // Let's get all text after #pricing-cards or all headings, tables, etc.
  const pricingEl = document.querySelector('#pricing-cards');
  let next = pricingEl;
  const sections = [];
  while (next) {
    sections.push({
      tagName: next.tagName,
      id: next.id,
      className: next.className,
      text: next.innerText
    });
    next = next.nextElementSibling;
  }
  return sections;
});
console.log("Sections count:", pageDetails.length);
pageDetails.forEach((s, idx) => {
  console.log(`--- Section ${idx} (${s.tagName} #${s.id} .${s.className}) ---`);
